// contractSatInertReplay answers zeros where Replay should act.
type contractSatInertReplay struct{ chain.Contract }

func (contractSatInertReplay) Replay(_ context.Context) (z0 []chain.Entry, z1 error) {
	return
}

// contractSatFlickerReplay answers zeros every second
// call, where Replay should answer the same thing twice.
//
// The defect every stability claim names: cacheable, deterministic,
// consistent, non-decreasing are all about two calls agreeing, and a subject
// that answers zeros *forever* agrees with itself perfectly. Only an answer
// that changes breaks them, and alternating with the zero is the smallest
// change available at any return type.
type contractSatFlickerReplay struct {
	chain.Contract
	flip atomic.Int64
}

func (m *contractSatFlickerReplay) Replay(p0 context.Context) (z0 []chain.Entry, z1 error) {
	if m.flip.Add(1)%2 == 0 {
		return
	}
	return m.Contract.Replay(p0)
}

// contractSatSputterReplay alternates a minted refusal
// with the real answer where Replay should be steady.
type contractSatSputterReplay struct {
	chain.Contract
	flip atomic.Int64
}

func (m *contractSatSputterReplay) Replay(p0 context.Context) (z0 []chain.Entry, z1 error) {
	if m.flip.Add(1)%2 == 1 {
		z1 = errors.New("contract: saturation sputtered a refusal")
		return
	}
	return m.Contract.Replay(p0)
}

// contractSatFadeReplay answers every second replay
// reversed and short one — the log lying about what it already showed.
type contractSatFadeReplay struct {
	chain.Contract
	flip atomic.Int64
}

func (m *contractSatFadeReplay) Replay(p0 context.Context) ([]chain.Entry, error) {
	out, err := m.Contract.Replay(p0)
	if err != nil || m.flip.Add(1)%2 == 1 || len(out) == 0 {
		return out, err
	}
	faded := slices.Clone(out)
	slices.Reverse(faded)
	return faded[:len(faded)-1], nil
}

// contractSatJumbleReplay answers every drain
// reversed, where Replay's order claim says one order holds.
//
// Every drain, not every second one. A claim read off a single drain is
// answered by whichever call the law makes, and the prover isolates one law
// at a time — so an alternating defect lands entirely on the parity the law
// never sees, and survives a wear built to break it.
type contractSatJumbleReplay struct{ chain.Contract }

func (m contractSatJumbleReplay) Replay(p0 context.Context) ([]chain.Entry, error) {
	out, err := m.Contract.Replay(p0)
	if err != nil {
		return out, err
	}
	jumbled := slices.Clone(out)
	slices.Reverse(jumbled)
	return jumbled, nil
}

// contractSatDupdrainReplay answers every drain with
// its first element repeated at the end, where Replay's claim says no
// element appears twice.
//
// Appended rather than doubled in place: a drain whose every element repeats
// is also out of order under most comparisons, and a defect that trips two
// claims cannot show which one it belongs to.
type contractSatDupdrainReplay struct{ chain.Contract }

func (m contractSatDupdrainReplay) Replay(p0 context.Context) ([]chain.Entry, error) {
	out, err := m.Contract.Replay(p0)
	if err != nil || len(out) == 0 {
		return out, err
	}
	return append(slices.Clone(out), out[0]), nil
}

// contractSatFloodReplay answers a drain past any
// limit a test can wait for, where Replay's claim says it terminates.
//
// Bounded, because the drain is what runs out of memory otherwise: the
// completion law reads its limit after the drain returns, so an endless
// answer takes the machine rather than the test.
type contractSatFloodReplay struct{ chain.Contract }

func (m contractSatFloodReplay) Replay(p0 context.Context) ([]chain.Entry, error) {
	out, err := m.Contract.Replay(p0)
	if err != nil {
		return out, err
	}
	return append(slices.Clone(out),
		make([]chain.Entry, testkit.FloodLimit)...), nil
}

